// Screen lock hides the desktop UI behind a PIN while the node keeps running,
// so a paired phone stays connected. The lock state is persisted, so a reload
// comes back locked; the caller signs out once attemptsLeft reaches zero.

import {reactive} from "vue";
import {argon2idAsync} from "@noble/hashes/argon2";
import {bytesToHex, hexToBytes, randomBytes} from "@noble/hashes/utils";

export const MAX_UNLOCK_ATTEMPTS = 5;
export const PIN_PATTERN = /^\d{4,8}$/;
export const IDLE_MINUTES_CHOICES = [0, 1, 5, 15, 30, 60];

const STORAGE_PREFIX = "warpnet.lock.";
const IDLE_CHECK_MS = 15000;
const ARGON2_PARAMS = {t: 2, m: 19456, p: 1, dkLen: 32};
const ACTIVITY_EVENTS = ["pointerdown", "pointermove", "keydown", "wheel", "touchstart"];

export const screenLock = reactive({
  isEnabled: false,
  isLocked: false,
  idleMinutes: 0,
  attemptsLeft: MAX_UNLOCK_ATTEMPTS,
});

let ownerId = "";
let lastActivityAt = 0;
let idleCheck = null;

function load(key) {
  try {
    return JSON.parse(localStorage.getItem(key) || "null");
  } catch (e) {
    return null;
  }
}

function store(key, value) {
  try {
    if (value === null) {
      localStorage.removeItem(key);
      return;
    }
    localStorage.setItem(key, JSON.stringify(value));
  } catch (e) {}
}

function configKey(userId) {
  return `${STORAGE_PREFIX}${userId}`;
}

function stateKey(userId) {
  return `${STORAGE_PREFIX}${userId}.state`;
}

function saveState() {
  store(stateKey(ownerId), {isLocked: screenLock.isLocked, attemptsLeft: screenLock.attemptsLeft});
}

async function hashPin(pin, salt) {
  return bytesToHex(await argon2idAsync(pin, salt, ARGON2_PARAMS));
}

function onActivity(e) {
  lastActivityAt = Date.now();
  if (e.type === "keydown" && (e.ctrlKey || e.metaKey) && e.key?.toLowerCase() === "l") {
    e.preventDefault();
    lockScreen();
  }
}

// Listeners run only while unlocked; the interval (rather than one timeout)
// also catches an idle period that spans a system sleep.
function syncWatchers() {
  clearInterval(idleCheck);
  idleCheck = null;
  for (const type of ACTIVITY_EVENTS) {
    document.removeEventListener(type, onActivity, true);
  }
  if (!screenLock.isEnabled || screenLock.isLocked) {
    return;
  }
  for (const type of ACTIVITY_EVENTS) {
    document.addEventListener(type, onActivity, true);
  }
  lastActivityAt = Date.now();
  if (screenLock.idleMinutes > 0) {
    idleCheck = setInterval(() => {
      if (Date.now() - lastActivityAt >= screenLock.idleMinutes * 60000) {
        lockScreen();
      }
    }, IDLE_CHECK_MS);
  }
}

// Every check counts against the attempts, the settings page included, so no
// screen offers unlimited guesses; once they run out only sign-out is left.
async function checkPin(pin) {
  const config = load(configKey(ownerId));
  if (!config || screenLock.attemptsLeft <= 0) {
    return false;
  }
  const isMatch = (await hashPin(String(pin || ""), hexToBytes(config.salt))) === config.hash;
  screenLock.attemptsLeft = isMatch ? MAX_UNLOCK_ATTEMPTS : Math.max(0, screenLock.attemptsLeft - 1);
  saveState();
  return isMatch;
}

// attachScreenLock binds the lock to the signed-in owner; an empty id (signed
// out) detaches it but keeps the stored state for the next restore.
export function attachScreenLock(userId) {
  ownerId = userId || "";
  const config = ownerId ? load(configKey(ownerId)) : null;
  const state = (config && load(stateKey(ownerId))) || {};
  screenLock.isEnabled = Boolean(config);
  screenLock.idleMinutes = config?.idleMinutes || 0;
  screenLock.isLocked = Boolean(config) && state.isLocked === true;
  screenLock.attemptsLeft = Number.isInteger(state.attemptsLeft) ? state.attemptsLeft : MAX_UNLOCK_ATTEMPTS;
  syncWatchers();
}

// A password login proves more than any PIN, so it clears the lock state.
export function resetScreenLock(userId) {
  store(stateKey(userId), null);
  if (userId !== ownerId) {
    return;
  }
  screenLock.isLocked = false;
  screenLock.attemptsLeft = MAX_UNLOCK_ATTEMPTS;
  syncWatchers();
}

export function lockScreen() {
  if (!screenLock.isEnabled || screenLock.isLocked) {
    return;
  }
  screenLock.isLocked = true;
  saveState();
  syncWatchers();
}

export async function unlockScreen(pin) {
  if (!(await checkPin(pin))) {
    return false;
  }
  screenLock.isLocked = false;
  saveState();
  syncWatchers();
  return true;
}

// updateScreenLock sets the PIN and idle timeout; changing an existing lock
// takes the current PIN, and an empty newPin keeps the stored one.
export async function updateScreenLock({currentPin, newPin, idleMinutes}) {
  const config = load(configKey(ownerId));
  if (config && !(await checkPin(currentPin))) {
    return false;
  }
  if (!config && !PIN_PATTERN.test(newPin || "")) {
    throw new Error("PIN must be 4 to 8 digits");
  }
  const next = {...config, idleMinutes: IDLE_MINUTES_CHOICES.includes(idleMinutes) ? idleMinutes : 0};
  if (newPin) {
    if (!PIN_PATTERN.test(newPin)) {
      throw new Error("PIN must be 4 to 8 digits");
    }
    const salt = randomBytes(16);
    next.salt = bytesToHex(salt);
    next.hash = await hashPin(newPin, salt);
  }
  store(configKey(ownerId), next);
  screenLock.isEnabled = true;
  screenLock.idleMinutes = next.idleMinutes;
  syncWatchers();
  return true;
}

export async function removeScreenLock(currentPin) {
  if (!(await checkPin(currentPin))) {
    return false;
  }
  store(configKey(ownerId), null);
  store(stateKey(ownerId), null);
  attachScreenLock(ownerId);
  return true;
}
